import { normalizeProject } from './core/commands';
import type { Project } from './core/types';
import { publicUrl } from './publicUrl';

export interface ExampleInfo {
  id: string;
  name: string;
  file: string;
  description: string;
}

/** Example projects shipped in public/examples (generated by scripts/make-examples.ts). */
export const EXAMPLES: ExampleInfo[] = [
  { id: 'wave-hello', name: 'Wave hello', file: 'wave-hello.mdoll.json', description: 'One doll, hand-keyed wave.' },
  { id: 'dance-crew', name: 'Dance crew', file: 'dance-crew.mdoll.json', description: 'Group of 5 dancing, with an animated render camera.' },
  { id: 'sword-duel', name: 'Sword duel', file: 'sword-duel.mdoll.json', description: 'Two dolls facing each other: combo and block.' },
];

export async function fetchExample(id: string): Promise<Project> {
  const ex = EXAMPLES.find((e) => e.id === id);
  if (!ex) throw new Error('Unknown example: ' + id);
  const res = await fetch(publicUrl('examples/' + ex.file));
  if (!res.ok) throw new Error(`Example not found (HTTP ${res.status})`);
  return normalizeProject(await res.json());
}
